sql.where:
sul.sys_log_from IN ('LOGIN', 'LOGIN_FAIL', 'LOGOUT')

  
  
  
    AND sul.sys_log_username <> 'sa'
  
  
    AND sul.sys_log_username <> 'sa'
    AND NOT EXISTS (
      SELECT 1
      FROM sys_user privileged_su
      LEFT JOIN sys_user_role privileged_sur ON privileged_sur.sys_user_id = privileged_su.sys_user_id
      LEFT JOIN sys_role privileged_sr ON privileged_sr.sys_role_id = privileged_sur.sys_role_id
      WHERE privileged_su.sys_user_username = sul.sys_log_username
        AND privileged_sr.sys_role_code IN ('ADMIN', 'SUPER_ADMIN')
    )
    AND (
      sul.create_by = #{sysUserId}
      
        OR EXISTS (
          SELECT 1
          FROM sys_dept managed_sd
          WHERE managed_sd.sys_dept_id = sul.sys_dept_id
            AND (
              
                managed_sd.sys_dept_tree_id LIKE CONCAT(#{treeId}, '%')
              
            )
        )
      
    )
  
  
    AND sul.create_by = #{sysUserId}
  


  AND sul.sys_log_username LIKE CONCAT('%', #{query.sysLogUsername}, '%')


  AND sul.sys_log_from LIKE CONCAT('%', #{query.sysLogFrom}, '%')


  AND sul.sys_log_address LIKE CONCAT('%', #{query.sysLogAddress}, '%')


  AND sul.sys_log_ip LIKE CONCAT('%', #{query.sysLogIp}, '%')


  AND sul.sys_log_status = #{query.sysLogStatus}


  AND sul.create_time >= #{query.startDate}


  AND sul.create_time <= #{query.endDate}

mapper.select:
SELECT sul.* FROM sys_user_log sul WHERE sul.sys_log_from = 'LOGIN' AND sul.sys_log_status = 1 AND sul.sys_log_username IN
#{username}
ORDER BY sul.create_time DESC, sul.sys_log_id DESC

SELECT sul.sys_log_username AS username, sul.sys_log_ip AS ip, MAX(sul.sys_log_address) AS address, MAX(sul.create_time) AS last_time, COUNT(*) AS total FROM sys_user_log sul WHERE sul.sys_log_from = 'LOGIN' AND sul.sys_log_status = 1 AND sul.sys_log_ip IS NOT NULL AND sul.sys_log_ip <> '' AND sul.sys_log_username IN
#{username}
GROUP BY sul.sys_log_username, sul.sys_log_ip ORDER BY last_time DESC

SELECT sul.sys_log_username AS username, CAST(sul.create_time AS DATE) AS login_date, COUNT(*) AS total, SUM(CASE WHEN sul.sys_log_status = 1 THEN 1 ELSE 0 END) AS success, SUM(CASE WHEN sul.sys_log_status = 0 THEN 1 ELSE 0 END) AS fail, MAX(sul.create_time) AS last_time, GROUP_CONCAT(DISTINCT sul.sys_log_ip SEPARATOR ',') AS ips FROM sys_user_log sul WHERE sul.sys_log_from IN ('LOGIN', 'LOGIN_FAIL') AND sul.create_time >= #{startTime} AND sul.sys_log_username IN
#{username}
GROUP BY sul.sys_log_username, CAST(sul.create_time AS DATE) ORDER BY login_date ASC
